// ===== núcleo (src/nucleo) — generado por scripts/build_flujos.js, no editar a mano =====
// Utilidades de texto del núcleo. JS puro, sin dependencias.

// minúsculas, sin tildes, espacios simples, sin puntuación en los bordes.
function normalizar(s) {
  if (s === null || s === undefined) return '';
  var t = String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  t = t.replace(/\s+/g, ' ').trim();
  // quita todo lo que no sea letra/número en los bordes
  t = t.replace(/^[^a-z0-9]+/, '').replace(/[^a-z0-9]+$/, '');
  return t;
}

// Número tolerante: acepta número o texto con coma o punto decimal ("62,5"). Vacío o basura -> null.
function num(v) {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  if (typeof v !== 'string') return null;
  var t = v.trim();
  if (!/^-?\d+(?:[.,]\d+)?$/.test(t)) return null;
  return Number(t.replace(',', '.'));
}

// Protege un valor de texto antes de escribirlo en la hoja: si empieza con = + @ o parece fecha corta ("1/2"),
// le antepone un apóstrofo. Números, booleanos y vacíos pasan sin cambio (null/undefined -> '').
function limpio(v) {
  if (v === null || v === undefined) return '';
  if (typeof v !== 'string') return v;
  if (/^[=+@]/.test(v) || /^\d{1,2}\/\d{1,2}(\/\d{2,4})?$/.test(v)) return "'" + v;
  return v;
}

if (typeof module !== 'undefined') module.exports = { normalizar: normalizar, num: num, limpio: limpio };
// Resolución de nombres libres de ejercicio contra el catálogo.
var _t_cat = (function () { try { return require('./texto'); } catch (e) { return { normalizar: normalizar }; } })();

function _distancia(a, b) {
  if (a === b) return 0;
  var prev = [], cur = [], i, j;
  for (j = 0; j <= b.length; j++) prev[j] = j;
  for (i = 1; i <= a.length; i++) {
    cur = [i];
    for (j = 1; j <= b.length; j++) {
      var c = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + c);
    }
    prev = cur;
  }
  return prev[b.length];
}

function _umbral(largo) {
  return Math.min(2, Math.floor(largo * 0.2));
}

// -> {estado:'exacto'|'sinonimo'|'dudoso'|'desconocido', ejercicio:<entrada>|null, candidatos:[<entrada>]}
// Nunca devuelve 'exacto' por aproximación: lo aproximado es 'dudoso'.
function resolverEjercicio(nombreLibre, catalogo) {
  var norm = _t_cat.normalizar(nombreLibre);
  var lista = Array.isArray(catalogo) ? catalogo : [];
  if (!norm) return { estado: 'desconocido', ejercicio: null, candidatos: [] };

  var exactos = [], sinonimos = [];
  lista.forEach(function (e) {
    if (!e || !e.ejercicio) return;
    if (_t_cat.normalizar(e.ejercicio) === norm) { exactos.push(e); return; }
    var sins = Array.isArray(e.sinonimos) ? e.sinonimos : [];
    for (var i = 0; i < sins.length; i++) {
      if (_t_cat.normalizar(sins[i]) === norm) { sinonimos.push(e); return; }
    }
  });
  if (exactos.length === 1 && sinonimos.length === 0) return { estado: 'exacto', ejercicio: exactos[0], candidatos: [] };
  if (exactos.length === 0 && sinonimos.length === 1) return { estado: 'sinonimo', ejercicio: sinonimos[0], candidatos: [] };
  var ambiguos = exactos.concat(sinonimos);
  if (ambiguos.length > 1) return { estado: 'dudoso', ejercicio: null, candidatos: ambiguos.slice(0, 3) };

  // aproximado
  var puntuados = [];
  lista.forEach(function (e) {
    if (!e || !e.ejercicio) return;
    var nombres = [e.ejercicio].concat(Array.isArray(e.sinonimos) ? e.sinonimos : []);
    var mejor = null;
    nombres.forEach(function (n) {
      var nn = _t_cat.normalizar(n);
      if (!nn) return;
      var d = _distancia(norm, nn);
      if (d <= _umbral(Math.max(norm.length, nn.length)) && (mejor === null || d < mejor)) mejor = d;
    });
    if (mejor !== null) puntuados.push({ e: e, d: mejor });
  });
  puntuados.sort(function (a, b) { return a.d - b.d; });
  if (puntuados.length) {
    return { estado: 'dudoso', ejercicio: null, candidatos: puntuados.slice(0, 3).map(function (p) { return p.e; }) };
  }
  return { estado: 'desconocido', ejercicio: null, candidatos: [] };
}

if (typeof module !== 'undefined') module.exports = { resolverEjercicio: resolverEjercicio };
// Unidades, placas de máquina y modalidades.

var MODALIDADES = ['normal', 'lastre', 'asistida', 'corporal'];
var LB_A_KG = 0.45359237;

var _UNI_KG = ['kg', 'kgs', 'kilo', 'kilos', 'kilogramo', 'kilogramos'];
var _UNI_LB = ['lb', 'lbs', 'libra', 'libras'];

function _normUnidad(u) {
  return String(u === null || u === undefined ? '' : u).toLowerCase().replace(/\./g, '').trim();
}

// Devuelve {kg, convertido}. Unidad o valor no válidos -> {kg:null, convertido:false}.
function aKg(valor, unidad) {
  var v = valor;
  if (typeof valor === 'string') v = /^\s*-?\d+(?:[.,]\d+)?\s*$/.test(valor) ? Number(valor.replace(',', '.')) : NaN;
  if (typeof v !== 'number' || !isFinite(v)) return { kg: null, convertido: false };
  var u = _normUnidad(unidad);
  if (_UNI_KG.indexOf(u) !== -1) return { kg: v, convertido: false };
  if (_UNI_LB.indexOf(u) !== -1) return { kg: Math.round(v * LB_A_KG * 2) / 2, convertido: true };
  return { kg: null, convertido: false };
}

var _ORDINALES = {
  primera: 1, primer: 1, segunda: 2, segundo: 2, tercera: 3, tercer: 3, cuarta: 4, cuarto: 4,
  quinta: 5, quinto: 5, sexta: 6, sexto: 6, septima: 7, septimo: 7, octava: 8, octavo: 8,
  novena: 9, noveno: 9, decima: 10, decimo: 10
};
var _PLACA = '(?:placas?|plaquetas?|plaquitas?)';

function _sinTildes(t) {
  return String(t === null || t === undefined ? '' : t).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Busca una placa en el texto. Devuelve {placa, inicio, fin} (índices sobre el texto
// en minúsculas y sin tildes) o null.
function buscarPlaca(texto) {
  var t = _sinTildes(texto);
  var m;
  // "la cuarta placa"
  m = new RegExp('\\b(?:la\\s+)?(' + Object.keys(_ORDINALES).join('|') + ')\\s+' + _PLACA + '\\b').exec(t);
  if (m) return { placa: _ORDINALES[m[1]], inicio: m.index, fin: m.index + m[0].length };
  // "placa 4", "placa n° 4"
  m = new RegExp('\\b' + _PLACA + '\\s*(?:n(?:o|\\u00ba|\\u00b0)?\\.?\\s*)?(\\d{1,2})\\b').exec(t);
  if (m) return { placa: parseInt(m[1], 10), inicio: m.index, fin: m.index + m[0].length };
  // "4 placas" (no "4x8 placa", donde el 8 son reps)
  m = new RegExp('(?:^|[^x\\u00d7\\d])(\\d{1,2})\\s+' + _PLACA + '\\b').exec(t);
  if (m && /placas|plaquetas|plaquitas/.test(m[0])) {
    var ini = m.index + m[0].indexOf(m[1]);
    return { placa: parseInt(m[1], 10), inicio: ini, fin: m.index + m[0].length };
  }
  return null;
}

function leerPlaca(texto) {
  var r = buscarPlaca(texto);
  return r ? r.placa : null;
}

if (typeof module !== 'undefined') {
  module.exports = { aKg: aKg, leerPlaca: leerPlaca, buscarPlaca: buscarPlaca, MODALIDADES: MODALIDADES, LB_A_KG: LB_A_KG };
}
// Resolución de fechas en America/Bogota. Luxon: global DateTime (n8n) o carga desde el repo (Node).
var _ZONA_F = 'America/Bogota';
var _luxonDT = null;

function inyectarLuxon(DT) { _luxonDT = DT; }

function _obtenerDT() {
  if (_luxonDT) return _luxonDT;
  if (typeof DateTime !== 'undefined') { _luxonDT = DateTime; return _luxonDT; }
  if (typeof require === 'function') {
    var rutas = ['luxon', '../../.claude/skills/n8n-workflow-check/node_modules/luxon'];
    for (var i = 0; i < rutas.length; i++) {
      try { _luxonDT = require(rutas[i]).DateTime; if (_luxonDT) return _luxonDT; } catch (e) { /* siguiente */ }
    }
  }
  throw new Error('Luxon no disponible: usa inyectarLuxon(DateTime)');
}

function _sinTildesF(t) {
  return String(t).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function _aDT(ahora) {
  var DT = _obtenerDT();
  var d;
  if (ahora && ahora.isLuxonDateTime) d = ahora.setZone(_ZONA_F);
  else if (ahora instanceof Date) d = DT.fromJSDate(ahora, { zone: _ZONA_F });
  else if (typeof ahora === 'string') d = DT.fromISO(ahora, { zone: _ZONA_F });
  else throw new Error('ahora inválido');
  if (!d.isValid) throw new Error('ahora inválido');
  return d;
}

var _DIAS = { lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6, domingo: 7 };
var _MESES = {
  enero: 1, ene: 1, febrero: 2, feb: 2, marzo: 3, mar: 3, abril: 4, abr: 4, mayo: 5, may: 5, junio: 6, jun: 6,
  julio: 7, jul: 7, agosto: 8, ago: 8, septiembre: 9, setiembre: 9, sept: 9, sep: 9, set: 9,
  octubre: 10, oct: 10, noviembre: 11, nov: 11, diciembre: 12, dic: 12
};

function _fin(hoy, d) {
  if (!d || !d.isValid) return { ok: false, motivo: 'no_entendida' };
  if (d.toISODate() > hoy.toISODate()) return { ok: false, motivo: 'futura' };
  return { ok: true, fecha: d.toISODate() };
}

function _construir(DT, y, m, d) {
  var x = DT.fromObject({ year: y, month: m, day: d }, { zone: _ZONA_F });
  return x.isValid ? x : null;
}

// -> {ok:true, fecha:'AAAA-MM-DD'} | {ok:false, motivo:'futura'|'no_entendida'}
function resolverFecha(texto, ahora) {
  var DT = _obtenerDT();
  var hoy = _aDT(ahora).startOf('day');
  var t = (texto === null || texto === undefined) ? '' : _sinTildesF(texto);
  t = t.replace(/[.,;!]+$/, '').trim();
  if (t === '' || t === 'hoy') return { ok: true, fecha: hoy.toISODate() };
  if (t === 'ayer') return { ok: true, fecha: hoy.minus({ days: 1 }).toISODate() };
  if (t === 'anteayer' || t === 'antier' || t === 'antes de ayer') return { ok: true, fecha: hoy.minus({ days: 2 }).toISODate() };
  if (t === 'manana' || t === 'pasado manana') return { ok: false, motivo: 'futura' };

  var m;
  // ISO
  m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(t);
  if (m) return _fin(hoy, _construir(DT, +m[1], +m[2], +m[3]));

  // día de la semana: "el lunes", "lunes pasado", "este lunes"
  m = /^(?:el |este |ese )?(lunes|martes|miercoles|jueves|viernes|sabado|domingo)(?: pasado)?$/.exec(t);
  if (m) {
    var atras = (hoy.weekday - _DIAS[m[1]] + 7) % 7;
    return { ok: true, fecha: hoy.minus({ days: atras }).toISODate() };
  }

  // d/m o d/m/aaaa o d-m
  m = /^(?:el )?(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2}|\d{4}))?$/.exec(t);
  if (m) {
    var anio = m[3] ? (m[3].length === 2 ? 2000 + (+m[3]) : +m[3]) : hoy.year;
    return _fin(hoy, _construir(DT, anio, +m[2], +m[1]));
  }

  // "7 de octubre", "7 oct", "7 de octubre de 2026"
  m = /^(?:el )?(\d{1,2}) ?(?:de )?([a-z]+)(?: (?:de )?(\d{4}))?$/.exec(t);
  if (m && _MESES[m[2]]) {
    var a2 = m[3] ? +m[3] : hoy.year;
    return _fin(hoy, _construir(DT, a2, _MESES[m[2]], +m[1]));
  }
  return { ok: false, motivo: 'no_entendida' };
}

if (typeof module !== 'undefined') module.exports = { resolverFecha: resolverFecha, inyectarLuxon: inyectarLuxon, _aDT: _aDT };
// Atajo sin IA para patrones frecuentes de registro de series.
// Devuelve [{ejercicioTexto, series:[{n, unidad, pesoKg, placa, modalidad, reps, [segundos], [convertido]}]}] o null si no está seguro.
var _t_ser = (function () { try { return require('./texto'); } catch (e) { return { normalizar: normalizar }; } })();
var _u_ser = (function () { try { return require('./unidades'); } catch (e) { return { aKg: aKg, buscarPlaca: buscarPlaca }; } })();
var _c_ser = (function () { try { return require('./catalogo'); } catch (e) { return { resolverEjercicio: resolverEjercicio }; } })();

var _UNI_RE = '(kg|kgs|kilos?|kilogramos?|lb|lbs|libras?)';
var _CORPORAL_RE = /^(dominadas?|fondos|flexiones|pull ?ups?|chin ?ups?|lagartijas|paralelas)\b/;
var _FECHA_RE = /\b(ayer|anteayer|antier|manana|lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b|\b\d{1,2}\/\d{1,2}\b|\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2} de [a-z]+/;
var _ENCABEZADO_RE = /^(hoy|entrene|hice|rutina de hoy|dia de|sesion de hoy)\b/;
var _MAX_REPS_ATAJO = 50;
var _MAX_SERIES_ATAJO = 20;

function _base(s) {
  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function _esPalabraFrontera(tok, sig) {
  if (/^\d/.test(tok)) return true;
  if (/^(con|lastre|asistid[oa]s?|ayuda|banda)$/.test(tok)) return true;
  if (/^(placas?|plaquetas?|plaquitas?)$/.test(tok)) return true;
  if (/^(primera|primer|segunda|tercera|tercer|cuarta|quinta|sexta|septima|octava|novena|decima)$/.test(tok) &&
      sig && /^(placas?|plaquetas?|plaquitas?)$/.test(sig)) return true;
  if (tok === 'la' && sig && /^(primera|segunda|tercera|cuarta|quinta|sexta|septima|octava|novena|decima)$/.test(sig)) return true;
  return false;
}

function _esCorporal(nombre, catalogo) {
  var res = catalogo ? _c_ser.resolverEjercicio(nombre, catalogo) : null;
  if (res && res.ejercicio) return res.ejercicio.tipo === 'peso corporal';
  return _CORPORAL_RE.test(_base(nombre));
}

function _parsearSegmento(seg, catalogo) {
  var palabras = seg.split(/\s+/);
  var toks = palabras.map(function (p) { return _base(p).replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ''); });
  var corte = -1;
  for (var i = 0; i < toks.length; i++) {
    if (_esPalabraFrontera(toks[i], toks[i + 1])) { corte = i; break; }
  }
  if (corte <= 0) return null; // sin nombre o sin datos
  var nombre = palabras.slice(0, corte).join(' ').replace(/[,:\-]+$/, '').trim();
  if (!/[a-zA-ZñÑáéíóúÁÉÍÓÚ]/.test(nombre)) return null;
  var r = ' ' + _base(palabras.slice(corte).join(' ')) + ' ';

  // coma decimal pegada a unidad: "12,5 kg" -> "12.5 kg"
  r = r.replace(new RegExp('(\\d+),(\\d{1,2})(?=\\s*' + _UNI_RE + '\\b)', 'g'), '$1.$2');

  var modalidad = null;
  if (/\blastre\b/.test(r)) { modalidad = 'lastre'; r = r.replace(/\b(con )?lastre\b/, ' '); }
  else if (/\b(asistid[oa]s?|ayuda|banda)\b/.test(r)) {
    modalidad = 'asistida';
    r = r.replace(/\b(asistid[oa]s?|con ayuda|ayuda|con banda|banda)\b/, ' ');
  }

  var placa = null;
  var bp = _u_ser.buscarPlaca(r);
  if (bp) { placa = bp.placa; r = r.slice(0, bp.inicio) + ' ' + r.slice(bp.fin); }

  var pesoKg = null, convertido = false, hayPeso = false;
  var mp = new RegExp('(\\d+(?:\\.\\d+)?)\\s*' + _UNI_RE + '\\b').exec(r);
  if (mp) {
    var conv = _u_ser.aKg(parseFloat(mp[1]), mp[2]);
    if (conv.kg === null) return null;
    pesoKg = conv.kg; convertido = conv.convertido; hayPeso = true;
    r = r.slice(0, mp.index) + ' ' + r.slice(mp.index + mp[0].length);
  }
  if (hayPeso && placa !== null) return null;

  // segundos (ejercicios de tiempo): "3x45 s", "3 series de 45 s", "45 s, 40 s"
  var SEG = '(?:s|seg|segs|segundos?)';
  var segList = null;
  var ms1 = new RegExp('(\\d+)\\s*(?:[x\u00d7]|series?\\s+de)\\s*(\\d+)\\s*' + SEG + '\\b').exec(r);
  if (ms1) {
    var ns = parseInt(ms1[1], 10);
    if (ns < 1 || ns > _MAX_SERIES_ATAJO) return null;
    segList = [];
    for (var z = 0; z < ns; z++) segList.push(parseInt(ms1[2], 10));
    r = r.slice(0, ms1.index) + ' ' + r.slice(ms1.index + ms1[0].length);
  } else if (new RegExp('\\d\\s*' + SEG + '\\b').test(r)) {
    var re = new RegExp('(\\d+)\\s*' + SEG + '\\b', 'g'), mm;
    segList = [];
    while ((mm = re.exec(r))) segList.push(parseInt(mm[1], 10));
    r = r.replace(re, ' ');
  }
  if (segList) {
    r = r.replace(/\b(y|e|con|de)\b|,/g, ' ');
    if (r.trim() !== '' || hayPeso || placa !== null || modalidad !== null) return null;
    if (segList.length > _MAX_SERIES_ATAJO || segList.some(function (x) { return x < 1 || x > 3600; })) return null;
    return {
      ejercicioTexto: nombre,
      series: segList.map(function (sg, idx) {
        return { n: idx + 1, unidad: 'kg', pesoKg: null, placa: null, modalidad: 'normal', reps: null, segundos: sg };
      })
    };
  }

  // "3 series de 10" / "3 series 10" = 3x10; cualquier otro "series" suelto es ambiguo -> null
  r = r.replace(/(\d+)\s*series?\s*(?:de\s*)?(\d+)(?!\d)/, ' $1x$2 ');
  if (/\d\s*series?\b|\bseries?\s*\d/.test(r)) return null;

  var nSeries = null, repsFijas = null;
  var mx = /(\d+)\s*[x×]\s*(\d+)/.exec(r);
  if (mx) {
    nSeries = parseInt(mx[1], 10); repsFijas = parseInt(mx[2], 10);
    r = r.slice(0, mx.index) + ' ' + r.slice(mx.index + mx[0].length);
    // número suelto restante (con o sin "con") = peso en kg
    if (!hayPeso && placa === null) {
      var ms = /^\s*(?:con\s+)?(\d+(?:\.\d+)?)\s*$/.exec(r);
      if (ms) { pesoKg = parseFloat(ms[1]); hayPeso = true; r = ' '; }
    }
  }

  r = r.replace(/\b(reps|repeticiones|series|con|de)\b/g, ' ');
  var reps = [];
  if (repsFijas !== null) {
    if (r.trim() !== '') return null;
    if (nSeries < 1 || nSeries > _MAX_SERIES_ATAJO) return null;
    for (var k = 0; k < nSeries; k++) reps.push(repsFijas);
  } else {
    if (!/^[\d\s,y]*$/.test(r.replace(/\be\b/g, ' '))) return null;
    var nums = r.match(/\d+/g);
    if (!nums || nums.length > _MAX_SERIES_ATAJO) return null;
    reps = nums.map(function (x) { return parseInt(x, 10); });
  }
  for (var q = 0; q < reps.length; q++) if (reps[q] < 1 || reps[q] > _MAX_REPS_ATAJO) return null;
  // sin unidad de peso ni placa y con números que parecen peso ("curl 20 10 8"): no adivina
  if (!hayPeso && placa === null && modalidad === null && repsFijas === null &&
      reps.some(function (x) { return x > 12; }) && !_esCorporal(nombre, catalogo)) return null;

  // modalidad
  if (modalidad === null) {
    var corporal = _esCorporal(nombre, catalogo);
    modalidad = (corporal && !hayPeso && placa === null) ? 'corporal' : 'normal';
  }

  var series = reps.map(function (rp, idx) {
    var s = {
      n: idx + 1,
      unidad: placa !== null ? 'placa' : 'kg',
      pesoKg: placa !== null ? null : (hayPeso ? pesoKg : null),
      placa: placa,
      modalidad: modalidad,
      reps: rp
    };
    if (convertido) s.convertido = true;
    return s;
  });
  return { ejercicioTexto: nombre, series: series };
}

function atajoSeries(texto, catalogo) {
  if (typeof texto !== 'string' || !texto.trim()) return null;
  if (_FECHA_RE.test(_base(texto))) return null; // la fecha la resuelve el flujo/IA
  var segmentos = texto.split(/\r?\n|;|\.(?=\s|$)/).map(function (s) { return s.trim(); }).filter(Boolean);
  var salida = [];
  for (var i = 0; i < segmentos.length; i++) {
    var seg = segmentos[i];
    var b = _base(seg);
    if (!/\d/.test(b)) {
      if (_ENCABEZADO_RE.test(b)) continue; // "Hoy pecho y tríceps"
      return null;
    }
    seg = seg.replace(/^\s*hoy[\s,:]+/i, '');
    var p = _parsearSegmento(seg, catalogo);
    if (!p) return null;
    salida.push(p);
  }
  return salida.length ? salida : null;
}

if (typeof module !== 'undefined') module.exports = { atajoSeries: atajoSeries };
// Validación y normalización de un registro de entrenamiento. Nunca rellena peso/reps.
